<div class="card"><h2>Очередь проверки</h2><ul><?php foreach ( $snapshot['queue'] as $reason => $count ) : ?><li><a href="<?php echo esc_url( add_query_arg( array( 'post_type' => 'promocode', 'page' => 'admitad-review', 'reason' => $reason ), admin_url( 'edit.php' ) ) ); ?>"><?php echo esc_html( $reason . ': ' . $count ); ?></a></li><?php endforeach; ?></ul></div><div class="card"><h2>Расписание</h2><ul><?php foreach ( $snapshot['cron'] as $job => $event ) : ?><li><?php echo esc_html( $job . ': ' . ( $event['scheduled'] ? wp_date( 'Y-m-d H:i:s', $event['timestamp'] ) : 'не запланировано' ) ); ?></li><?php endforeach; ?></ul></div>
